import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Vizhinjam Ancient Port Explorer Tests",()=>{it("HTML contains all required sections: historical overview, natural harbor significance, maritime trade, timeline, gallery, and references",()=>{const e=readFileSync(resolve(__dirname,"../../vizhinjam-port-explorer/index.html"),"utf-8");expect(e).toContain('id="overview"'),expect(e).toContain('id="harbor-significance"'),expect(e).toContain('id="maritime-trade"'),expect(e).toContain('id="timeline"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Vizhinjam"),expect(e).toContain("Ay Dynasty"),expect(e).toContain("deep-water"),expect(e).toContain("Chola")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../vizhinjam-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-dark"),expect(e).toContain("--port-gold"),expect(e).toContain("--port-teal"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes clean and registers search items",()=>{const e=readFileSync(resolve(__dirname,"../../vizhinjam-port-explorer/script.js"),"utf-8");expect(e).toContain("initVizhinjamPortExplorer"),expect(e).toContain("setupGalleryModal"),expect(e).toContain("vizhinjam-port-explorer/index.html")}),it("Landing Page Integration: Ancient Ports explorer landing page includes Vizhinjam card",()=>{const e=readFileSync(resolve(__dirname,"../../ancient-ports-explorer/index.html"),"utf-8");expect(e).toContain("Vizhinjam Ancient Port"),expect(e).toContain("../vizhinjam-port-explorer/index.html")})});